"""Portable observation gallery and32-page case PDF from actual native measurements."""
import json,base64,html,sys
from pathlib import Path
from PIL import Image
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib.utils import ImageReader
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.platypus import Paragraph
from reportlab.lib.styles import ParagraphStyle
def esc(s):return html.escape(str(s))
def fmt(v):return 'NA' if v is None else f'{v:.4f}'
def text(g):return g['decoded'].strip() or ('[NL]' if '\n' in g['decoded'] else '[space]')
def main():
    P=Path(sys.argv[1]);data=json.loads((P/'analysis_data.json').read_text(encoding='utf-8'));cases=data['cases'];font=next(x for x in [Path('C:/Windows/Fonts/arial.ttf'),Path('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf')] if x.exists());pdfmetrics.registerFont(TTFont('Text',str(font)));pdf=canvas.Canvas(str(P/'case_cards.pdf'),pagesize=A4);W,H=A4;cards=[];layouts=[]
    for i,c in enumerate(cases):
        v=c['case'];s=v['sample'];q=v['question_id'];groups=v['groups'];stats={r['group_id']:r for r in c['band_groups']['L0-15']};orange=set(c['orange_groups']);image=P/v['gallery_image'];heat=P/'heatmaps'/(q+'.png');im=Image.open(image);iw,ih=im.size;ratio=min(250/iw,175/ih);dw,dh=iw*ratio,ih*ratio
        def para(t,x,y,width,size=9,color='#172b3a'):
            pp=Paragraph(t,ParagraphStyle('p',fontName='Text',fontSize=size,leading=size*1.32,textColor=color));_,h=pp.wrap(width,2000);pp.drawOn(pdf,x,y-h);return y-h
        def header(part):
            pdf.setFillColor('#19364a');pdf.rect(0,H-58,W,58,fill=1,stroke=0);pdf.setFillColor('white');pdf.setFont('Text',14);pdf.drawString(28,H-25,f'{i+1:02d} | {q} | {s["task"]} | {v["kind"]}');pdf.setFont('Text',8);pdf.drawString(28,H-44,'NATIVE FULL OBSERVATION | '+part+' | no new answer generation')
        def footer(page):
            pdf.setFillColor('#697b88');pdf.setFont('Text',7.5);pdf.drawString(28,18,f'ATE | Attention allocation is not causal importance | Page {page}/32')
        header('metrics');y=para(esc(s['question']),28,H-70,W-56,12)-10;pdf.drawImage(ImageReader(im),28,y-dh,width=dw,height=dh)
        yy=para('Gold: <b>'+esc(s['answer'])+'</b><br/>Historical All-Writer: '+esc(v['history_answers']['All-Writer']['text'])+'<br/>Historical Semantic-k: '+esc(v['history_answers']['Semantic-k']['text']),300,y,W-328,10)-7
        yy=para('P-1 is separate (not in R ranking):<br/>'+ '<br/>'.join(f'{b}: M={fmt(c["p_minus_one"][b]["mass_mean"])}' for b in ['L8-11','L0-15','L16-19','L0-31']),300,yy,W-328,9)
        y=min(y-dh,yy)-14;y=para('Question groups below: L0-15 averages over all heads/layers/subwords. M=Mass, E=Excess, En=mean per-head Enrichment. Green=historical selected; gray=omitted; orange border=relative omitted top5, not a causal threshold.',28,y,W-56,8)-10
        chips=[];x=28;bh=53
        for g in [g for g in groups if g['scope']=='Question']:
            r=stats[g['group_id']];width=max(75,min(115,pdfmetrics.stringWidth(text(g),'Text',9)+16));color='#d9f1df' if g['selected'] else '#e7ebef';edge='#d28422' if g['group_id'] in orange else color
            if x+width>W-28:x=28;y-=bh+5
            pdf.setFillColor(color);pdf.setStrokeColor(edge);pdf.setLineWidth(1.5 if g['group_id'] in orange else .5);pdf.roundRect(x,y-bh,width,bh,3,fill=1,stroke=1);pdf.setFillColor('#193141');pdf.setFont('Text',9);pdf.drawString(x+5,y-12,text(g));pdf.setFont('Text',6.5);pdf.drawString(x+5,y-23,f'@{g["positions"][0]} n={len(g["positions"])}');pdf.drawString(x+5,y-33,'M '+fmt(r['mass_mean'])+' E '+fmt(r['excess_mean']));pdf.drawString(x+5,y-44,'En '+fmt(r['enrichment_mean']));x+=width+5
            chips.append(f'<span class="chip {"selected" if g["selected"] else "omitted"} {"high" if g["group_id"] in orange else ""}"><b>{esc(text(g))}</b><small>p={g["positions"]}; n={len(g["positions"])}</small><small>M={fmt(r["mass_mean"])} E={fmt(r["excess_mean"])} En={fmt(r["enrichment_mean"])}</small></span>')
        y-=bh+16;y=para('Other R groups (Instruction and Assistant/template); all historically omitted. Exact subwords and all-layer metrics are preserved in CSV.',28,y,W-56,8)-10
        pdf.setFont('Text',8);pdf.drawString(28,y,'Group / positions');pdf.drawString(260,y,'Scope');pdf.drawString(375,y,'Mass');pdf.drawString(433,y,'Excess');pdf.drawString(495,y,'Enrich.');y-=14
        for g in [g for g in groups if g['scope']!='Question']:
            r=stats[g['group_id']];pdf.setFont('Text',8);pdf.drawString(28,y,text(g)+' @'+','.join(map(str,g['positions'])));pdf.drawString(260,y,'Instruction' if g['scope']=='Instruction' else 'Assistant/template');pdf.drawString(375,y,fmt(r['mass_mean']));pdf.drawString(433,y,fmt(r['excess_mean']));pdf.drawString(495,y,fmt(r['enrichment_mean']));y-=12
        y=para('Template [space] immediately after Image is distinct from the ASSISTANT word. Negative Excess and Enrichment below1 mean the observed mass is below the uniform per-key baseline.',28,y-9,W-56,8,'#805500');assert y>34,(q,'metrics',y);layouts.append(dict(question_id=q,page=2*i+1,bottom=y));footer(2*i+1);pdf.showPage()
        header('layer heatmap and omitted Top5');heatim=Image.open(heat);ww=W-48;hh=ww*heatim.height/heatim.width;pdf.drawImage(ImageReader(heatim),24,H-72-hh,width=ww,height=hh);y=H-72-hh-9
        y=para('Omitted whole-group Top5 by scope (all32 heads averaged, no single-head maximum ranking):',28,y,W-56,9)-8
        sections=[]
        for band in ['L8-11','L0-15','L16-19']:
            y=para('<b>'+band+'</b>',28,y,W-56,10)-4;lines=[]
            for scope in ['Question','Instruction','Assistant/template']:
                rr=sorted([r for r in c['band_groups'][band] if r['scope']==scope and not r['semantic_selected']],key=lambda r:(-r['mass_mean'],r['first_position']))[:5]
                phrase='; '.join((r['group_text'].strip() or ('[NL]' if '\n' in r['group_text'] else '[space]'))+' @'+str(r['first_position'])+' '+f'{r["mass_mean"]:.3f}' for r in rr)
                y=para('<b>'+esc(scope)+':</b> '+esc(phrase),28,y,W-56,7.5)-4
                lines.append(f'<tr><th>{esc(scope)}</th><td>'+ '; '.join(esc((r['group_text'].strip() or ('[NL]' if '\n' in r['group_text'] else '[space]')))+f' @{r["first_position"]} M={r["mass_mean"]:.4f} E={r["excess_mean"]:.4f} En={fmt(r["enrichment_mean"])}' for r in rr)+'</td></tr>')
            sections.append(f'<h4>{band} — omitted Top5 per scope</h4><table>'+''.join(lines)+'</table>');y-=5
        y=para('L31 R outputs cannot propagate onward to the first-answer P-1 position in the answer-image-blocked causal graph. High L31 mass is not evidence of functional necessity. All answers shown are historical, not Native Full generation in this run.',28,y,W-56,8,'#9a4e00');assert y>35,(q,'heatmap',y);layouts.append(dict(question_id=q,page=2*i+2,bottom=y));footer(2*i+2);pdf.showPage()
        uri='data:image/jpeg;base64,'+base64.b64encode(image.read_bytes()).decode();huri='data:image/png;base64,'+base64.b64encode(heat.read_bytes()).decode()
        other=''.join(f'<tr><td>{esc(text(g))}</td><td>{g["positions"]}</td><td>{esc(g["scope"])}</td><td>{fmt(stats[g["group_id"]]["mass_mean"])}</td><td>{fmt(stats[g["group_id"]]["excess_mean"])}</td><td>{fmt(stats[g["group_id"]]["enrichment_mean"])}</td></tr>' for g in groups if g['scope']!='Question')
        subs=''.join(f'<tr><td>{r["position"]}</td><td>{esc(r["piece"])}</td><td>{esc(r["scope"])}</td><td>{r["selected"]}</td><td>{fmt(r["mass_mean"])}</td><td>{fmt(r["excess_mean"])}</td><td>{fmt(r["enrichment_mean"])}</td></tr>' for r in c['subword_L0_15'])
        cards.append(f'<article class="case" id="case-{q}" data-kind="{v["kind"]}"><h2>{i+1:02d} | {q} | {s["task"]} | {v["kind"]}</h2><h3>{esc(s["question"])}</h3><div class="pair"><img class="original" src="{uri}"><div><p>Gold: <b>{esc(s["answer"])}</b></p><p>历史All-Writer：{esc(v["history_answers"]["All-Writer"]["text"])}</p><p>历史Semantic-k：{esc(v["history_answers"]["Semantic-k"]["text"])}</p><p>本轮Native Full只采集Prefill，不生成答案。</p><p>P−1 @{s["input_mapping"]["p_minus_one"]} 独立显示：全32层平均M={fmt(c["p_minus_one"]["L0-31"]["mass_mean"])}；L0–15 M={fmt(c["p_minus_one"]["L0-15"]["mass_mean"])}</p></div></div><p>完整Question词组：绿色＝历史Semantic选中；灰色＝未选；橙框＝L0–15内未选Question相对Top5。下面数值均为该层段平均，M=Mass，E=Excess，En=逐Head Enrichment均值。</p><div class="chips">{"".join(chips)}</div><h4>Instruction / Assistant-template（L0–15；边界与ASSISTANT勿混同）</h4><div class="scroll"><table><tr><th>完整词组</th><th>实际位置</th><th>角色</th><th>M</th><th>E</th><th>En</th></tr>{other}</table></div><img class="heatmap" src="{huri}" alt="Native Full32 layer text group heatmap {q}">{"".join(sections)}<details><summary>逐Subword真实数值（L0–15）；逐层/逐Head完整数据见CSV</summary><div class="scroll"><table><tr><th>位置</th><th>Subword</th><th>角色</th><th>历史S</th><th>M</th><th>E</th><th>En</th></tr>{subs}</table></div></details><p class="note">Attention分配不等于因果重要性。P−1不在R排序中；L31的R输出不能继续影响第一答案位置。未把历史All-Writer当作本轮Native Full答案。</p></article>')
    pdf.save();doc='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ATE Native Full遗漏视觉接收者</title><style>*{box-sizing:border-box}body{margin:0;background:#eef2f5;color:#183045;font:15px/1.6 Arial,"Microsoft YaHei",sans-serif}main{max-width:1220px;margin:auto;padding:24px}header{background:#19364a;color:white;padding:26px;border-radius:10px}.case{padding:26px;margin:25px 0;background:white;border-radius:10px}h2{overflow-wrap:anywhere}.pair{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:22px}.original{width:100%;height:290px;object-fit:contain}.chips{display:flex;flex-wrap:wrap;gap:7px}.chip{padding:7px;border:2px solid transparent;border-radius:5px}.chip small{display:block;font:11px/1.5 Consolas,monospace}.selected{background:#d9f1df}.omitted{background:#e7ebef}.high{border-color:#d28422}.heatmap{width:100%;height:auto;margin-top:24px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:7px;border-bottom:1px solid #dde3e8;text-align:left;overflow-wrap:anywhere}.note{padding:14px;background:#fff2d5;color:#805000}.controls{margin:15px 0}select,input{font:inherit;padding:8px}details{margin-top:18px}@media(max-width:650px){main{padding:12px}.case{padding:16px}.pair{display:block}.chip small{font-size:10px}}[hidden]{display:none!important}</style><main><header><h1>Native Full：哪些未选Token在看图？</h1><p>固定16例、32层×32个Head；所有原始Attention连接开放。显示真实观测，无新答案生成。</p><p>576个Image Key形成很高的Uniform Baseline；原始Mass大不等于Excess为正或Enrichment&gt;1。橙框是预先固定的相对排名，不是因果判定。</p></header><div class="controls"><select id="kind"><option value="">全部16例</option><option value="harm">12个错误案例</option><option value="rescue">4个纠正反例</option></select><input id="search" placeholder="搜索Question ID或问题"><span id="count">16 /16</span></div>'''+''.join(cards)+'''</main><script>const cs=[...document.querySelectorAll('.case')],k=document.getElementById('kind'),s=document.getElementById('search');function run(){let n=0;for(const c of cs){c.hidden=!!((k.value&&c.dataset.kind!==k.value)||(s.value&&!c.textContent.toLowerCase().includes(s.value.toLowerCase())));if(!c.hidden)n++}document.getElementById('count').textContent=n+' /16'}k.oninput=run;s.oninput=run;</script></html>''';(P/'gallery.html').write_text(doc,encoding='utf-8');(P/'card_layout_validation.json').write_text(json.dumps(dict(pages=32,attention_observed=True,all_bottoms_above_footer=True,layout=layouts),indent=2));print('RENDER COMPLETE32 PAGES')
if __name__=='__main__':main()
